-- 📚 꼭집 주거 사전 — 순위 구조 — 매입 신혼·신생아 1~5순위 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 4.8초 · 결과:
-- {"anns": 46, "by_std": {"공공임대(6·10·50년)": 7, "국민임대": 4, "매입임대": 30, "영구임대": 1, "전세임대": 2, "행복주택": 2}, "신혼5순위": 19, "신혼5순위_ex": ["SH_310653", "SH_310650", "21390_부산광역시_사하구"], "5순위까지": 10, "5순위까지_ex": ["SH_310653", "21390_부산광역시_사하구", "2015122300020841"], "선순위신청": 2, "선순위신청_ex": ["SH_310653", "SH_310650"], "수급자1순위": 11, "수급자1순위_ex": ["2015122300020842", "2015122300020839", "2015122300020838"], "청약저축순위": 6, "청약저축순위_ex": ["2015122300020895", "2015122300020856", "2015122300020765"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='순위'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='순위' group by 1)q),'신혼5순위',(select count(distinct announcement_id) from y where cls='순위' and t~'1\s*순위[^■]{0,120}신생아[^■]{0,250}2\s*순위[^■]{0,80}미성년\s*자녀'),'신혼5순위_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='순위' and t~'1\s*순위[^■]{0,120}신생아[^■]{0,250}2\s*순위[^■]{0,80}미성년\s*자녀' order by 1 desc limit 3)q),'5순위까지',(select count(distinct announcement_id) from y where cls='순위' and t~'5\s*순위'),'5순위까지_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='순위' and t~'5\s*순위' order by 1 desc limit 3)q),'선순위신청',(select count(distinct announcement_id) from y where cls='순위' and t~'선순위[^.]{0,20}(자격|으로)'),'선순위신청_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='순위' and t~'선순위[^.]{0,20}(자격|으로)' order by 1 desc limit 3)q),'수급자1순위',(select count(distinct announcement_id) from y where cls='순위' and t~'1\s*순위[^.]{0,60}(생계|의료|주거)\s*급여'),'수급자1순위_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='순위' and t~'1\s*순위[^.]{0,60}(생계|의료|주거)\s*급여' order by 1 desc limit 3)q),'청약저축순위',(select count(distinct announcement_id) from y where cls='순위' and t~'(청약\s*(저축|통장)|주택청약종합저축)[^.]{0,40}(순위|납입)'),'청약저축순위_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='순위' and t~'(청약\s*(저축|통장)|주택청약종합저축)[^.]{0,40}(순위|납입)' order by 1 desc limit 3)q))j;
